.contact-details p {
    color: #64748b;
    font-size: 1.05rem;
}

.contact-form {
    background-color: #fff;
    padding: 2.5rem;
    border-radius: 20px;
    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.08);
